let selectedRecipe=0,coins=120,stats={hunger:62,energy:78,fun:70},clockMin=480,walking=false,cooking=false,hover=null,target=null,camYaw=0,camPitch=0,dragging=false,lastX=0,lastY=0;
const recipes=[{name:'Оладушки',emoji:'🥞',time:'8 мин',cost:6,hunger:32,fun:12,desc:'Пышные, с ягодами и мёдом'},{name:'Паста с томатами',emoji:'🍝',time:'12 мин',cost:10,hunger:42,fun:15,desc:'Домашний соус и свежий базилик'},{name:'Омлет с зеленью',emoji:'🍳',time:'6 мин',cost:5,hunger:27,fun:8,desc:'Сытный завтрак на скорую руку'}];
const $=s=>document.querySelector(s),overlay=$('#recipeOverlay'),recipesBox=$('#recipes'),hint=$('#keyhint'),interaction=$('#interaction');
recipesBox.innerHTML=recipes.map((r,i)=>`<button class="recipe ${i===0?'selected':''}" data-recipe="${i}"><span class="food">${r.emoji}</span><span class="recipename">${r.name}</span><span class="recipeinfo">${r.desc}</span><span class="recipefoot"><span>⏱ ${r.time}</span><br><span>🪙 ${r.cost}</span></span></button>`).join('');
recipesBox.addEventListener('click',e=>{let b=e.target.closest('[data-recipe]');if(!b)return;selectedRecipe=+b.dataset.recipe;document.querySelectorAll('.recipe').forEach((el,i)=>el.classList.toggle('selected',i===selectedRecipe))});
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2400)}
function needs(){for(const k of Object.keys(stats)){stats[k]=Math.max(0,Math.min(100,stats[k]));$(`#${k}Fill`).style.width=stats[k]+'%';$(`#${k}Num`).textContent=Math.round(stats[k])}}
function setCoins(){ $('#coins').textContent=coins }
function setClock(){const h=Math.floor(clockMin/60)%24,m=clockMin%60;$('#clock').textContent=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')}
function advance(minutes){clockMin+=minutes;setClock();stats.energy-=minutes*.035;stats.hunger-=minutes*.035;needs()}
setInterval(()=>{if(!cooking){advance(1);}},6000);
function openRecipes(){overlay.classList.add('open')}
$('#recipeAction').onclick=openRecipes;$('#closeModal').onclick=()=>overlay.classList.remove('open');overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.classList.remove('open')});
$('#startCooking').onclick=()=>{overlay.classList.remove('open');beginCooking()};
function beginCooking(){if(cooking){toast('Уже готовим!');return}if(coins<recipes[selectedRecipe].cost){toast('Не хватает монет на продукты');return}cooking=true;coins-=recipes[selectedRecipe].cost;setCoins();$('#objective').textContent='Лиза готовит '+recipes[selectedRecipe].name.toLowerCase();$('#progressText').textContent='Достань продукты из холодильника';hint.classList.remove('show');toast('Поехали! Сначала достанем продукты 🧺');runCooking()}
async function runCooking(){const recipe=recipes[selectedRecipe],steps=[{p:new THREE.Vector3(-4.1,0,-.55),text:'Продукты уже на столе — смешиваем ингредиенты'},{p:new THREE.Vector3(-2.9,0,-2.4),text:'Почти готово — добавим щепотку любви'},{p:new THREE.Vector3(-1.65,0,-2.05),text:'Готовим на плите…'}];for(let i=0;i<steps.length;i++){if(!cooking)return;$('#progressText').textContent=steps[i].text;moveTo(steps[i].p);await waitForStop();if(!cooking)return;advance(i===2?recipe.time==='12 мин'?5:3:2);if(i===2){body.rotation.y=0;arms.forEach((a,n)=>a.rotation.z=n===0?-.75:.75);for(let t=0;t<3;t++){await sleep(650);if(!cooking)return;spawnSteam(-1.65,1.9,-2.05)}arms.forEach(a=>a.rotation.z=0)}else await sleep(350)}
if(!cooking)return;cooking=false;stats.fun+=recipe.fun;stats.hunger=Math.min(100,stats.hunger+recipe.hunger);stats.energy=Math.max(0,stats.energy-3);coins+=8+Math.round(recipe.fun/3);setCoins();needs();$('#objective').textContent='Приготовь что-нибудь вкусное!';$('#progressText').textContent='Блюдо готово — пора попробовать!';$('#cookAction').querySelector('span:last-child').textContent='Поесть';$('#cookAction').classList.add('primary');target=null;walking=false;toast(`${recipe.emoji} ${recipe.name} готово! Восстановлены силы · +${8+Math.round(recipe.fun/3)} монет`);advance(2);}
function waitForStop(){return new Promise(resolve=>{let tries=0;const check=()=>{if(!walking||tries++>150)resolve();else setTimeout(check,70)};check()})}const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function moveTo(p){target=p.clone();walking=true;}
function nearest(){let best=null,dist=2.2;for(const it of interactables){const d=Math.hypot(sim.position.x-it.pos.x,sim.position.z-it.pos.z);if(d<dist){best=it;dist=d}}return best}
function interact(it){if(!it){toast('Подойди поближе к предмету');return}switch(it.act){case'fridge':toast('Холодильник полон — сегодня готовим что-нибудь вкусное!');openRecipes();break;case'stove':if(cooking)toast('На плите уже готовится блюдо');else openRecipes();break;case'table':if($('#cookAction').querySelector('span:last-child').textContent==='Поесть'){stats.hunger=Math.min(100,stats.hunger+15);stats.fun=Math.min(100,stats.fun+4);needs();$('#cookAction').querySelector('span:last-child').textContent='Готовить';$('#progressText').textContent='Отличный завтрак!';$('#objective').textContent='Побалуй себя чем-нибудь ещё';toast('М-м-м, очень вкусно! 🍽️')}else toast('Стол накрыт — приготовь блюдо и возвращайся!');break;case'sofa':stats.energy=Math.min(100,stats.energy+10);stats.fun=Math.min(100,stats.fun+8);needs();advance(15);toast('Лиза немного отдохнула на диване 🪴');break;case'sink':toast('Чистая посуда — чистая совесть! ✨');stats.fun=Math.min(100,stats.fun+3);needs();break}}
$('#fridgeAction').onclick=()=>{let it=interactables[0];moveTo(new THREE.Vector3(-4.1,0,-.55));setTimeout(()=>{if(Math.hypot(sim.position.x-it.pos.x,sim.position.z-it.pos.z)<2.5)interact(it);else openRecipes()},1800)};
$('#cookAction').onclick=()=>{if($('#cookAction').querySelector('span:last-child').textContent==='Поесть'){const it=interactables.find(i=>i.act==='table');moveTo(new THREE.Vector3(2.35,0,-.4));setTimeout(()=>interact(it),2000)}else openRecipes()};
$('#relaxAction').onclick=()=>{moveTo(new THREE.Vector3(4.05,0,2.1));setTimeout(()=>interact(interactables.find(i=>i.act==='sofa')),2200)};
// Invisible click targets and ground plane, allowing simple tap-to-walk controls
const ground=new THREE.Mesh(new THREE.PlaneGeometry(12,9),new THREE.MeshBasicMaterial({visible:false,side:THREE.DoubleSide}));ground.rotation.x=-Math.PI/2;ground.position.y=.12;scene.add(ground);
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let clickTargets=[];for(const it of interactables){const marker=new THREE.Mesh(new THREE.SphereGeometry(.55,12,10),new THREE.MeshBasicMaterial({visible:false}));marker.position.copy(it.pos);marker.userData.interactable=it;scene.add(marker);clickTargets.push(marker)}
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0)return;dragging=true;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)});
renderer.domElement.addEventListener('pointerup',e=>{if(!dragging)return;dragging=false;const moved=Math.hypot(e.clientX-lastX,e.clientY-lastY);if(moved>7)return;pointer.x=e.clientX/innerWidth*2-1;pointer.y=-(e.clientY/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects([...clickTargets,ground],false);if(!hits.length)return;const obj=hits[0].object;if(obj.userData.interactable){const it=obj.userData.interactable;hover=it;interaction.textContent=it.name+' · нажми E';interaction.classList.add('show');setTimeout(()=>interaction.classList.remove('show'),1400);let dx=sim.position.x-it.pos.x,dz=sim.position.z-it.pos.z,d=Math.hypot(dx,dz);if(d<2.1)interact(it);else moveTo(new THREE.Vector3(it.pos.x+dx/d*1.35,0,it.pos.z+dz/d*1.35))}else{const p=hits[0].point;moveTo(new THREE.Vector3(THREE.MathUtils.clamp(p.x,-5.1,5.1),0,THREE.MathUtils.clamp(p.z,-3.9,3.8)))}});
