window.addEventListener('keydown',e=>{if(overlay.classList.contains('open')){if(e.key==='Escape')overlay.classList.remove('open');return}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();const step=.65;if(e.key.toLowerCase()==='e'){let it=nearest();if(it)interact(it);else toast('Подойди ближе к холодильнику, плите или столу')}if(e.key.toLowerCase()==='w'||e.key==='ArrowUp')moveTo(new THREE.Vector3(sim.position.x,0,sim.position.z-.8));if(e.key.toLowerCase()==='s'||e.key==='ArrowDown')moveTo(new THREE.Vector3(sim.position.x,0,sim.position.z+.8));if(e.key.toLowerCase()==='a'||e.key==='ArrowLeft')moveTo(new THREE.Vector3(sim.position.x-.8,0,sim.position.z));if(e.key.toLowerCase()==='d'||e.key==='ArrowRight')moveTo(new THREE.Vector3(sim.position.x+.8,0,sim.position.z));if(e.code==='Space'){camYaw=0;camPitch=0}if(e.key==='Escape')overlay.classList.remove('open')});
