function updateCamera(){const focus=new THREE.Vector3(0,1.1,0),distance=18.8,pitch=.51+camPitch;camera.position.set(focus.x+Math.sin(camYaw)*Math.cos(pitch)*distance,focus.y+Math.sin(pitch)*distance,focus.z+Math.cos(camYaw)*Math.cos(pitch)*distance);camera.lookAt(focus)}
